WITH "__duckstream_0" AS (SELECT t.c0 AS c0, date_trunc('month', make_timestamp((CASE WHEN t.c1 IS NULL OR isfinite(t.c1) THEN epoch_us(t.c1) ELSE error('finite TIMESTAMP required') END))) AS c1, (make_timestamp((CASE WHEN date_trunc('month', make_timestamp((CASE WHEN t.c1 IS NULL OR isfinite(t.c1) THEN epoch_us(t.c1) ELSE error('finite TIMESTAMP required') END))) IS NULL OR isfinite(date_trunc('month', make_timestamp((CASE WHEN t.c1 IS NULL OR isfinite(t.c1) THEN epoch_us(t.c1) ELSE error('finite TIMESTAMP required') END)))) THEN epoch_us(date_trunc('month', make_timestamp((CASE WHEN t.c1 IS NULL OR isfinite(t.c1) THEN epoch_us(t.c1) ELSE error('finite TIMESTAMP required') END)))) ELSE error('finite TIMESTAMP required') END)) + to_months(-84)) AS c2, (make_timestamp((CASE WHEN t.c1 IS NULL OR isfinite(t.c1) THEN epoch_us(t.c1) ELSE error('finite TIMESTAMP required') END)) + to_months(-12)) AS c3 FROM (SELECT "id" AS c0, "instant" AS c1 FROM "calendar_inputs") t)
SELECT CAST(result.c0 AS INTEGER) AS "id", CAST(result.c1 AS TIMESTAMP) AS "month_start", CAST(result.c2 AS TIMESTAMP) AS "history_start", CAST(result.c3 AS TIMESTAMP) AS "prior_year" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3 FROM "__duckstream_0" v) result;
